-- Manual cue publications belong to an explicit library operation, not a fake analysis job.
DROP TRIGGER smart_cue_revisions_insert;
DROP TRIGGER smart_cue_revisions_delete;
DROP TRIGGER smart_cue_revisions_update;
ALTER TABLE cue_revisions RENAME TO old_cue_revisions;
CREATE TABLE cue_revisions (id TEXT PRIMARY KEY,track_id TEXT NOT NULL REFERENCES tracks(id),job_id TEXT REFERENCES jobs(id),json TEXT NOT NULL,created INTEGER NOT NULL);
INSERT INTO cue_revisions SELECT id,track_id,job_id,json,created FROM old_cue_revisions ORDER BY rowid;
DROP TABLE old_cue_revisions;
CREATE TRIGGER smart_cue_revisions_insert AFTER INSERT ON cue_revisions BEGIN UPDATE meta SET value=value+1 WHERE key='smart_input_revision'; END;
CREATE TRIGGER smart_cue_revisions_delete AFTER DELETE ON cue_revisions BEGIN UPDATE meta SET value=value+1 WHERE key='smart_input_revision'; END;
CREATE TRIGGER smart_cue_revisions_update AFTER UPDATE ON cue_revisions BEGIN UPDATE meta SET value=value+1 WHERE key='smart_input_revision'; END;
INSERT INTO meta VALUES('maintenance_entity_epoch',0);
CREATE TABLE maintenance_track_epochs(id TEXT PRIMARY KEY,epoch INTEGER NOT NULL);
CREATE TABLE maintenance_playlist_epochs(id TEXT PRIMARY KEY,epoch INTEGER NOT NULL);
INSERT INTO maintenance_track_epochs SELECT id,0 FROM tracks;
INSERT INTO maintenance_playlist_epochs SELECT id,0 FROM playlists;
CREATE TABLE maintenance_writes(id TEXT PRIMARY KEY,kind TEXT NOT NULL,state TEXT NOT NULL,payload_json TEXT NOT NULL,created INTEGER NOT NULL,error TEXT,cleanup_complete INTEGER NOT NULL DEFAULT 0);
CREATE TABLE maintenance_write_files(write_id TEXT NOT NULL REFERENCES maintenance_writes(id),ordinal INTEGER NOT NULL,target BLOB NOT NULL,staged BLOB NOT NULL,backup BLOB,before_hash TEXT,after_hash TEXT NOT NULL,publish_path BLOB NOT NULL,displaced_path BLOB NOT NULL,workspace BLOB NOT NULL,PRIMARY KEY(write_id,ordinal));
CREATE TRIGGER maintenance_epoch_tracks_insert AFTER INSERT ON tracks BEGIN UPDATE meta SET value=value+1 WHERE key='maintenance_entity_epoch';INSERT INTO maintenance_track_epochs VALUES(NEW.id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch; END;
CREATE TRIGGER maintenance_epoch_tracks_update AFTER UPDATE ON tracks BEGIN UPDATE meta SET value=value+1 WHERE key='maintenance_entity_epoch';INSERT INTO maintenance_track_epochs VALUES(OLD.id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch;INSERT INTO maintenance_track_epochs VALUES(NEW.id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch; END;
CREATE TRIGGER maintenance_epoch_tracks_delete AFTER DELETE ON tracks BEGIN UPDATE meta SET value=value+1 WHERE key='maintenance_entity_epoch';INSERT INTO maintenance_track_epochs VALUES(OLD.id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch; END;
CREATE TRIGGER maintenance_epoch_cue_revisions_insert AFTER INSERT ON cue_revisions BEGIN UPDATE meta SET value=value+1 WHERE key='maintenance_entity_epoch';INSERT INTO maintenance_track_epochs VALUES(NEW.track_id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch; END;
CREATE TRIGGER maintenance_epoch_cue_revisions_update AFTER UPDATE ON cue_revisions BEGIN UPDATE meta SET value=value+1 WHERE key='maintenance_entity_epoch';INSERT INTO maintenance_track_epochs VALUES(OLD.track_id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch;INSERT INTO maintenance_track_epochs VALUES(NEW.track_id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch; END;
CREATE TRIGGER maintenance_epoch_cue_revisions_delete AFTER DELETE ON cue_revisions BEGIN UPDATE meta SET value=value+1 WHERE key='maintenance_entity_epoch';INSERT INTO maintenance_track_epochs VALUES(OLD.track_id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch; END;
