CREATE TRIGGER maintenance_epoch_track_custom_tags_delete AFTER DELETE ON track_custom_tags BEGIN UPDATE meta SET value=value+1 WHERE key='maintenance_entity_epoch';INSERT INTO maintenance_track_epochs VALUES(OLD.track_id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch; END;
