CREATE TRIGGER maintenance_epoch_playlists_update AFTER UPDATE ON playlists BEGIN UPDATE meta SET value=value+1 WHERE key='maintenance_entity_epoch';INSERT INTO maintenance_playlist_epochs VALUES(OLD.id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch;INSERT INTO maintenance_playlist_epochs VALUES(NEW.id,(SELECT value FROM meta WHERE key='maintenance_entity_epoch')) ON CONFLICT(id) DO UPDATE SET epoch=excluded.epoch; END;
